tion(TDesignator* newSelection);		// Sets the designator for the user selection (if any). Defaults to setting the        // user selection of the document (if any)	virtual void UserSelectionChanged(TView* changedView);		// Call this whenever the user's selection changes. Defaults to calling the        // UserSelectionChanged method of the document (if any).	virtual void ScrollSelectionIntoView(bool redraw);		// Scroll the selection into view.	virtual bool HasPendingUpdate();	// was const;		// Returns true if there is a pending update event for this view, false if not.	virtual void Update();		// If its window is not NULL then does an update by calling DrawContents.	//------------------------------------------------------------------------------------	// Validation/ Invalidation Methods	//------------------------------------------------------------------------------------	virtual void ForceRedraw();		// Invalidates the entire view forcing a redraw.	void Invalidate(const CViewRect& badVRect);	void Invalidate(const CRect_AC& badRect);	void Invalidate(const RgnHandle badRgn);		// Invalidates an area of the view.	virtual void DoInvalidateRegion(const RgnHandle badRgn);		// Invalidates a Region by passing it to the superview		// Intersects badRgn with the visible extent then calls DoInvalidateRegion with the        // result. We can only call InvalidRgn on a grafPort belonging to a window, if        // your code calls InvalidRgn on a non-window grafPort, it will die miserably. So        // views forward up their superview chain until they reach a view which overrides        // DoInvalidateRegion (usually a window) which then makes the actual InvalidRgn call	void Validate(const CViewRect& goodVRect);	void Validate(const CRect_AC& goodRect);	void Validate(const RgnHandle goodRgn);		// Validates an area of the view.	virtual void DoValidateRegion(const RgnHandle goodRgn);		// Validates a Region by passing it to the superview		// Intersects goodRgn with the visible extent then calls DoValidateRegion with the        // result. We can only call ValidRgn on a grafPort belonging to a window, if your        // code calls ValidRgn on a non-window grafPort, it will die miserably. So views        // forward up their superview chain until they reach a view which overrides        // DoValidateRegion (usually a window) which then makes the actual ValidRgn call	virtual void RevealRect(const CViewRect& rectToReveal,							const CViewPoint& minToSee,							bool redraw);		// Scrolls a rect into view, with 'minToSee' being the point which will end up at        // the bottom of the view, i.e.the minimum amount to be seen and 'rectToReveal'        // the rect being scrolled.	void RevealTop(bool redraw);		// Scroll the top of a rect into view.	void RevealBottom(bool redraw);		// Scroll the bottom of a rect into view.	virtual void RevealUndoRedo(TCommand* command);		// Make this context visible after undo/redo.	//------------------------------------------------------------------------------------	// Mouse Handling Methods	//------------------------------------------------------------------------------------	virtual EventNumber GetEventNumber();		// Returns cNoEvent. Overridden by TControl.	virtual bool ContainsMouse(const CViewPoint& theMouse);		// Is the view point 'theMouse' currently in our view.	virtual void DoMouseCommand(CViewPoint&		theMouse,								TToolboxEvent*	event,								CPoint_AC		hysteresis);		// Posts a simple tracker which by default calls back tracking methods of this        // view. There are two possibilities here: 1) Override DoMouseCommand to post        // commands that represent more complex, even undoable actions.That command may        // either let its tracking call back the view's tracking methods (the default)        // which must be overridden to do anything useful or it may simply do all the        // tracking itself. This mostly depends on whether different commands returned        // from the view would have different tracking behavior.For example this is the        // approach taken by DrawShapes. 2) Override the view's tracking methods and let        // the default tracker them.For example this is the approach taken by TControl.	virtual void DoMouseUp(CViewPoint&		theMouse,						   TToolboxEvent*	event,						   CPoint_AC		hysteresis);		// Called for the most deeply nested view that contains the mouse.	//------------------------------------------------------------------------------------	// Cursor and Help Handling Methods	//------------------------------------------------------------------------------------	void RestrictRegionToVisible(RgnHandle aRegion);		// Restricts the region to the visible extent of this view	virtual bool HandlesCursor() const;		// Returns true, if this view tracks the mouse so that it can claim the cursor.        // The default returns true. If false, subviews may still get a chance to set the        // cursor, as determined by TView::SubViewsHandleCursor.	virtual bool LetsSubViewsHandleCursor() const;		// Returns true if this view should allow subviews a chance to set the cursor. If        // true, the subviews themselves may still return false for HandlesCursor. By        // setting both values false, cursor tracking can be turned off for an entire        // window, such as the clipboard window.	virtual bool HandlesHelp() const;		// Returns true, if this view tracks the mouse so that it can show help. The        // default returns true. If false, subviews may still get a chance to show help,        // as determined by TView::SubViewsHandleHelp.	virtual bool LetsSubViewsHandleHelp() const;		// Returns true if this view should allow subviews a chance to show help. The        // subviews themselves may still return false for HandlesHelp. By setting both        // values false, help can be turned off for an entire view hierarchy#if qWantsContextualMenus	virtual void GetContextualMenu(const CViewPoint&	theMouse,								   TToolboxEvent*		event,								   CContextualMenu&		contextualMenu);		// Set up a contextual menu.#endif	virtual void DoSetCursor(const CViewPoint&	localPoint,							 RgnHandle			cursorRegion);		// Can be overridden to set the cursor and compute a cursor region. The default        // sets the cursor to an arrow and uses TView::GetDefaultCursorRegion to compute the        // largest appropriate cursor region	virtual void DoUnsetCursor();		// Called against the last view that set the cursor when the cursor is set by		// the application or another view.	virtual ResNumber GetHelpID();		// Returns fHelpID.	virtual short GetHelpIndex();		// Returns fHelpIndex.	virtual ResNumber GetCursorID();		// Returns fCursorID.#if !qCarbon && !qMSWindows	virtual short GetHelpState();		// Returns kHMEnabledItem, kHMDisabledItem, etc.	virtual void GetHelpParameters(const CViewPoint&	localPoint,								   RgnHandle			helpRegion,								   HMMessageRecord&		helpMessage,								   CPoint_AC&			localQDTip,								   CRect_AC&			localQDRect,								   short&				balloonVariant);		// Determine the parameters needed for showing a help balloon for this view. The		// default calls the TApplication method of the same name which gets the information		// from a resource of type 'hdlg'. The fields fHelpID and fHelpIndex specify the		// resource and component within the resource containing the information for this		// view.	void DoShowBalloon(const CViewPoint&		localPoint,					   RgnHandle				helpRegion,					   const HMMessageRecord&	helpMessage,					   CPoint_AC				localQDTip,					   const CRect_AC&			localQDRect,					   short					balloonVariant);		// Show the help balloon.#endif	virtual void DoShowHelp(const CViewPoint& localPoint, RgnHandle helpRegion);		// Gets the help parameters and shows the help balloon.	virtual void GetDefaultCursorRegion(const CViewPoint&	loca